"""数据层：加载中文动作数据、派生字段、筛选与媒体白名单。"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

BASE = Path(__file__).resolve().parent
ROOT = BASE.parent
DATA_FILE = ROOT / "exercises-dataset" / "data" / "exercises_zh.json"
MEDIA_DIR = ROOT / "exercises-dataset" / "videos"


def _load() -> list[dict[str, Any]]:
    rows = json.loads(DATA_FILE.read_text(encoding="utf-8"))
    items: list[dict[str, Any]] = []
    for row in rows:
        item = dict(row)
        gif_url = str(item.get("gif_url") or "")
        item["gif"] = gif_url.split("/")[-1] if gif_url else ""
        items.append(item)
    return items


EXERCISES: list[dict[str, Any]] = _load()
BY_ID: dict[str, dict[str, Any]] = {item["id"]: item for item in EXERCISES}
TOTAL = len(EXERCISES)


def _sorted_unique(values: list[str]) -> list[str]:
    return sorted({v for v in values if v})


def facets() -> dict[str, list[str]]:
    """返回筛选栏所需的去重排序取值。"""
    return {
        "categories": _sorted_unique([e.get("category", "") for e in EXERCISES]),
        "targets": _sorted_unique([e.get("target", "") for e in EXERCISES]),
        "equipments": _sorted_unique([e.get("equipment", "") for e in EXERCISES]),
    }


def filter_exercises(
    category: str = "",
    target: str = "",
    equipment: str = "",
    q: str = "",
) -> list[dict[str, Any]]:
    """多条件 AND 筛选；空值表示不过滤；q 对名称做不区分大小写包含匹配。"""
    keyword = (q or "").strip().lower()
    result = []
    for item in EXERCISES:
        if category and item.get("category") != category:
            continue
        if target and item.get("target") != target:
            continue
        if equipment and item.get("equipment") != equipment:
            continue
        if keyword and keyword not in str(item.get("name", "")).lower():
            continue
        result.append(item)
    return result


def summary(item: dict[str, Any]) -> dict[str, Any]:
    """列表接口使用的精简字段。"""
    return {
        "id": item["id"],
        "name": item.get("name", ""),
        "category": item.get("category", ""),
        "body_part": item.get("body_part", ""),
        "equipment": item.get("equipment", ""),
        "target": item.get("target", ""),
        "muscle_group": item.get("muscle_group", ""),
        "gif": item.get("gif", ""),
    }


def get_exercise(exercise_id: str) -> dict[str, Any] | None:
    return BY_ID.get(exercise_id)


def media_path(name: str) -> Path | None:
    """只允许 videos 目录内已存在的 .gif 文件，拒绝路径穿越。"""
    if not name or "/" in name or "\\" in name or ".." in name:
        return None
    if not name.lower().endswith(".gif"):
        return None
    path = MEDIA_DIR / name
    if not path.is_file():
        return None
    return path

"""聊天层：模型配置加载、会话存储、上游流式请求与 SSE 转发。"""

from __future__ import annotations

import json
import threading
import time
from pathlib import Path
from typing import Any, AsyncIterator

import httpx

BASE = Path(__file__).resolve().parent
CONFIG_FILE = BASE / ".local" / "model.json"

# 会话存储：{session_id: {"exercise_id": str, "messages": [...], "created_at": float}}
SESSIONS: dict[str, dict[str, Any]] = {}
LOCK = threading.Lock()

MAX_MESSAGE_CHARS = 2000
# 短问答输出预算，最终受配置 max_output_tokens 钳制
CHAT_OUTPUT_BUDGET = 1024

SYSTEM_TEMPLATE = (
    "你是一名专业、耐心的健身教练，正在为用户解答动作相关问题。"
    "当前讨论的动作是《{name}》。\n"
    "动作描述：{desc}\n"
    "目标肌肉：{target}；协同肌肉：{secondary}；所需器械：{equipment}；分类：{category}。\n"
    "用户可能用“这个动作”指代它。回答使用简体中文，简洁分点，"
    "涉及伤病或疼痛时提醒用户咨询医生。"
)


class ConfigError(Exception):
    """模型配置缺失或字段不全。"""


def load_config() -> dict[str, Any]:
    """读取私密模型配置；只在内存中使用，不写日志、不回显。"""
    if not CONFIG_FILE.is_file():
        raise ConfigError("模型配置缺失，请检查 app/.local/model.json")
    try:
        cfg = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ConfigError("模型配置缺失，请检查 app/.local/model.json") from exc
    required = ("base_url", "model", "api_key", "protocol")
    if any(not cfg.get(key) for key in required):
        raise ConfigError("模型配置缺失，请检查 app/.local/model.json")
    return cfg


def build_system_message(exercise: dict[str, Any]) -> dict[str, str]:
    desc = (exercise.get("instructions") or {}).get("zh") or "暂无数据"
    secondary = "、".join(exercise.get("secondary_muscles") or []) or "暂无数据"
    content = SYSTEM_TEMPLATE.format(
        name=exercise.get("name", ""),
        desc=desc,
        target=exercise.get("target") or "暂无数据",
        secondary=secondary,
        equipment=exercise.get("equipment") or "暂无数据",
        category=exercise.get("category") or "暂无数据",
    )
    return {"role": "system", "content": content}


def get_session(session_id: str, exercise_id: str, exercise: dict[str, Any]) -> dict[str, Any]:
    """取会话；不存在或动作不一致时重建，保证动作间上下文隔离。"""
    with LOCK:
        session = SESSIONS.get(session_id)
        if session is None or session.get("exercise_id") != exercise_id:
            session = {
                "exercise_id": exercise_id,
                "messages": [build_system_message(exercise)],
                "created_at": time.time(),
            }
            SESSIONS[session_id] = session
        return session


def snapshot(session_id: str) -> list[dict[str, str]]:
    """返回发送给上游的消息快照（深拷贝，避免并发修改）。"""
    with LOCK:
        session = SESSIONS.get(session_id)
        if not session:
            return []
        return [dict(m) for m in session["messages"]]


def append_user(session_id: str, message: str) -> None:
    with LOCK:
        SESSIONS[session_id]["messages"].append({"role": "user", "content": message})


def append_assistant(session_id: str, text: str) -> None:
    with LOCK:
        session = SESSIONS.get(session_id)
        if session is not None and text:
            session["messages"].append({"role": "assistant", "content": text})


def reset_session(session_id: str) -> None:
    with LOCK:
        SESSIONS.pop(session_id, None)


def turn_count(session_id: str) -> int:
    with LOCK:
        session = SESSIONS.get(session_id)
        if not session:
            return 0
        return sum(1 for m in session["messages"] if m["role"] == "user")


def build_payload(cfg: dict[str, Any], messages: list[dict[str, str]]) -> dict[str, Any]:
    """按配置组装上游请求体：request_options 原样合入，预算受上限钳制。"""
    payload: dict[str, Any] = {"model": cfg["model"], "messages": messages, "stream": True}
    budget = CHAT_OUTPUT_BUDGET
    cap = cfg.get("max_output_tokens")
    if isinstance(cap, int) and cap > 0:
        budget = min(budget, cap)
    field = cfg.get("output_token_field") or "max_tokens"
    payload[field] = budget
    options = cfg.get("request_options")
    if isinstance(options, dict):
        payload.update(options)
    return payload


def endpoint(cfg: dict[str, Any]) -> str:
    base = str(cfg["base_url"]).rstrip("/")
    protocol = cfg.get("protocol") or "chat_completions"
    if protocol == "responses":
        return f"{base}/responses"
    return f"{base}/chat/completions"


def _extract_delta(chunk: dict[str, Any], protocol: str) -> str:
    if protocol == "responses":
        if chunk.get("type") in ("response.output_text.delta", "response.text.delta"):
            return chunk.get("delta") or ""
        return ""
    choices = chunk.get("choices") or []
    if not choices:
        return ""
    delta = choices[0].get("delta") or {}
    content = delta.get("content")
    return content if isinstance(content, str) else ""


async def stream_upstream(
    cfg: dict[str, Any], messages: list[dict[str, str]]
) -> AsyncIterator[str]:
    """向上游发起流式请求，逐段产出文本增量。"""
    protocol = cfg.get("protocol") or "chat_completions"
    headers = {
        "Authorization": f"Bearer {cfg['api_key']}",
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
    }
    timeout = httpx.Timeout(float(cfg.get("timeout") or 120), connect=15.0)
    async with httpx.AsyncClient(timeout=timeout) as client:
        async with client.stream(
            "POST", endpoint(cfg), json=build_payload(cfg, messages), headers=headers
        ) as resp:
            if resp.status_code >= 400:
                await resp.aread()
                raise RuntimeError(f"上游返回 {resp.status_code}")
            async for line in resp.aiter_lines():
                if not line or not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if not data or data == "[DONE]":
                    if data == "[DONE]":
                        break
                    continue
                try:
                    chunk = json.loads(data)
                except json.JSONDecodeError:
                    continue
                text = _extract_delta(chunk, protocol)
                if text:
                    yield text


def sse(event: str, data: dict[str, Any]) -> str:
    return f"event: {event}\ndata: {json.dumps(data, ensure_ascii=False)}\n\n"

"""FastAPI 应用入口：页面、数据、媒体与聊天流式接口。"""

from __future__ import annotations

import asyncio
import json
from pathlib import Path
from typing import Any, AsyncIterator

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import FileResponse, HTMLResponse, JSONResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles
from fastapi.templating import Jinja2Templates
from pydantic import BaseModel, Field

import chat
import data

BASE = Path(__file__).resolve().parent
templates = Jinja2Templates(directory=str(BASE / "tpl"))

app = FastAPI(title="健身动作库")
app.mount("/static", StaticFiles(directory=str(BASE / "static")), name="static")


class ChatIn(BaseModel):
    session_id: str = Field(min_length=1, max_length=120)
    exercise_id: str = Field(min_length=1, max_length=20)
    message: str = Field(min_length=1, max_length=chat.MAX_MESSAGE_CHARS)


class ResetIn(BaseModel):
    session_id: str = Field(min_length=1, max_length=120)


@app.exception_handler(Exception)
async def unhandled(request: Request, exc: Exception) -> JSONResponse:
    return JSONResponse(status_code=500, content={"detail": "服务暂时不可用，请稍后重试"})


@app.get("/", response_class=HTMLResponse)
async def index(request: Request) -> HTMLResponse:
    return templates.TemplateResponse(
        request,
        "index.html",
        {"facets": data.facets(), "total": data.TOTAL},
    )


@app.get("/api/exercises")
async def list_exercises(
    category: str = "", target: str = "", equipment: str = "", q: str = ""
) -> dict[str, Any]:
    items = data.filter_exercises(category=category, target=target, equipment=equipment, q=q)
    return {
        "total": data.TOTAL,
        "count": len(items),
        "items": [data.summary(item) for item in items],
    }


@app.get("/api/exercises/{exercise_id}")
async def exercise_detail(exercise_id: str) -> dict[str, Any]:
    item = data.get_exercise(exercise_id)
    if item is None:
        raise HTTPException(status_code=404, detail="未找到该动作")
    return item


@app.get("/media/{name}")
async def media(name: str) -> FileResponse:
    path = data.media_path(name)
    if path is None:
        raise HTTPException(status_code=404, detail="未找到该媒体文件")
    return FileResponse(path, media_type="image/gif")


@app.post("/api/chat/reset")
async def chat_reset(payload: ResetIn) -> dict[str, bool]:
    chat.reset_session(payload.session_id)
    return {"ok": True}


@app.post("/api/chat")
async def chat_stream(payload: ChatIn, request: Request) -> StreamingResponse:
    exercise = data.get_exercise(payload.exercise_id)
    if exercise is None:
        raise HTTPException(status_code=404, detail="未找到该动作")
    message = payload.message.strip()
    if not message:
        raise HTTPException(status_code=422, detail="消息不能为空")

    try:
        cfg = chat.load_config()
    except chat.ConfigError as exc:
        async def config_error() -> AsyncIterator[str]:
            yield chat.sse("error", {"message": str(exc)})
        return _stream(config_error())

    chat.get_session(payload.session_id, payload.exercise_id, exercise)
    chat.append_user(payload.session_id, message)
    messages = chat.snapshot(payload.session_id)
    turn = chat.turn_count(payload.session_id)

    async def events() -> AsyncIterator[str]:
        yield chat.sse(
            "meta",
            {"session_id": payload.session_id, "exercise_id": payload.exercise_id, "turn": turn},
        )
        parts: list[str] = []
        try:
            async for text in chat.stream_upstream(cfg, messages):
                if await request.is_disconnected():
                    return
                parts.append(text)
                yield chat.sse("delta", {"text": text})
        except asyncio.CancelledError:
            raise
        except Exception:
            yield chat.sse("error", {"message": "模型服务暂时不可用，请稍后重试"})
            return
        full = "".join(parts)
        if not full:
            yield chat.sse("error", {"message": "模型服务暂时不可用，请稍后重试"})
            return
        chat.append_assistant(payload.session_id, full)
        yield chat.sse("done", {"ok": True})

    return _stream(events())


def _stream(gen: AsyncIterator[str]) -> StreamingResponse:
    return StreamingResponse(
        gen,
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


@app.get("/api/health")
async def health() -> dict[str, Any]:
    return {"ok": True, "total": data.TOTAL, "config": chat.CONFIG_FILE.is_file()}


def _dump(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False)

:root {
