async function restoreHistory(sid, id, token) {
  /* 恢复状态按面板令牌隔离：只有当前面板的恢复请求才能改变 restoring */
  restoring = true;
  try {
    const p = new URLSearchParams({ session_id: sid, exercise_id: id });
    const res = await fetch(`/api/chat/history?${p.toString()}`);
    if (!res.ok) return;
    const data = await res.json();
    if (token !== current || !modal.open) return;
    if (!Array.isArray(data.messages) || data.messages.length === 0) return;
    if (logEl.querySelector(".bubble.user")) return;
    logEl.innerHTML = "";
    data.messages.forEach((m) => {
      bubble(m.role === "user" ? "user" : "bot", m.content);
    });
    suggestEl.hidden = true;
  } catch (err) {
    /* 历史恢复失败时保留欢迎语，不影响继续提问 */
  } finally {
    /* 过期面板（已关闭或已切换动作）不得复位新面板的 restoring */
    if (token === current) restoring = false;
  }
}

